<?php $s=app(\App\Repositories\BillingRepository::class)->state($booking); $token=$booking['access_token']; ?>
<section class="panel billing-admin"><div class="section-head"><div><span class="eyebrow">BILLING</span><h2>Invoice และการชำระเงิน</h2></div><?php if ($token): ?><a class="outline-link" target="_blank" rel="noopener noreferrer" href="<?= (base_url() . ('booking/detail/'.$token)) ?>">เปิดหน้าลูกค้า / คัดลอกลิงก์ ↗</a><?php endif ?></div>
<div class="seat-summary"><div><span>รับชำระแล้ว</span><strong>฿<?= money($s['paid']/100) ?></strong></div><div><span>คงเหลือ</span><strong>฿<?= money($s['remaining']/100) ?></strong></div></div>
<?php if ($s['invoice']): ?><p><a class="outline-link" target="_blank" rel="noopener" href="<?= (base_url() . ('booking/invoice/'.$token)) ?>"><?= e($s['invoice']['reference']) ?> ↗</a> · กำหนดชำระ <?= e($s['due']) ?></p><?php if ($s['due']<date('Y-m-d H:i:s') && $s['remaining']>0): ?><p class="notice">พ้นกำหนดชำระ · ที่นั่งยังถูกจองไว้ ตรวจสลิปและติดต่อผู้จองก่อนยกเลิก</p><?php endif ?><?php if ($booking['status']==='confirmed' && $s['remaining']>0): ?><form method="post" action="<?= (base_url() . ('admin/bookings/'.$booking['id'].'/extend')) ?>" class="form-grid"><?= csrf_field() ?><label>ปรับกำหนดชำระจากตอนนี้ (ชั่วโมง)<input type="number" name="hours" min="1" max="720" value="24" required></label><button class="btn" type="submit">บันทึกกำหนดชำระ</button></form><?php endif ?><?php else: ?><p>เลือกสถานะ “ยืนยันแล้ว” และบันทึก เพื่อออก Invoice และเปิดรับชำระเงิน</p><?php endif ?>
<?php if ($booking['status']==='cancelled' && $s['paid']>0): ?><p class="notice">การจองยกเลิกแล้ว แต่มียอดรับเงิน ฿<?= money($s['paid']/100) ?> · ตรวจสอบการคืนเงินกับลูกค้า ประวัติการรับเงินยังคงอยู่</p><?php endif ?>
<?php foreach ($s['payments'] as $p): ?><article class="payment-review"><h3><?= e($p['reference']) ?> · <?= e(payment_status_label($p['status'])) ?></h3><p>ยอดเรียกเก็บ ฿<?= money($p['expected_amount']) ?> · โอนจริง <?= $p['reported_amount']!==null ? '฿'.money($p['reported_amount']) : '—' ?></p><?php if ($p['slip_path']): ?><p>โอนเมื่อ <?= e($p['transferred_at']) ?> · <?= e($p['channel']) ?></p><a class="outline-link" href="<?= (base_url() . ('booking/slip/'.$token.'/'.$p['id'])) ?>" target="_blank" rel="noopener">เปิดสลิป ↗</a><?php endif ?>
<?php if ($p['status']==='pending'): ?><form method="post" action="<?= (base_url() . ('admin/payments/'.$p['id'])) ?>" class="stack-form"><?= csrf_field() ?><label>ผลตรวจ<select name="decision"><option value="approve">ยืนยันรับเงินและออกใบเสร็จ</option><option value="reject">ไม่ผ่าน / ขอหลักฐานใหม่</option></select></label><label>รายละเอียดผลตรวจ (ลูกค้ามองเห็น)<textarea name="review_note" maxlength="1000" rows="2"></textarea></label><?php if (app(\App\Repositories\BillingRepository::class)->cents($p['expected_amount'])!==app(\App\Repositories\BillingRepository::class)->cents($p['reported_amount'])): ?><label class="checkbox"><input type="checkbox" name="ack_difference" value="1"> ตรวจยอดต่างแล้ว ยืนยันรับตามยอดโอนจริง</label><?php endif ?><button type="submit" class="btn">บันทึกผลตรวจสลิป</button></form><?php endif ?><?php if ($p['review_note']): ?><p><?= e($p['review_note']) ?></p><?php endif ?><?php if ($p['status']==='approved'): ?><a class="document-link" target="_blank" rel="noopener" href="<?= (base_url() . ('booking/receipt/'.$token.'/'.$p['id'])) ?>">ใบเสร็จ <?= e($p['receipt_reference']) ?> ↗</a><?php endif ?></article><?php endforeach ?>
<details><summary>ประวัติการดำเนินการ</summary><ol class="booking-timeline"><?php foreach ($s['events'] as $event): ?><li><small><?= e($event['created_at']) ?> · <?= $event['actor_id'] ? 'ผู้ดูแล #'.(int)$event['actor_id'] : 'ลูกค้า / ระบบ' ?></small><p><?= e($event['message']) ?></p></li><?php endforeach ?></ol></details></section>
